def build(records, prefix):
    rows = []
    for index, (category, prompt, answer) in enumerate(records, 1):
        rows.append({
            "id": f"{prefix}-{index:03d}",
            "category": category,
            "mode": "ask",
            "messages": [{"role": "user", "content": prompt}, {"role": "assistant", "content": answer}],
            "tags": ["personality", "identity", f"sonderr:{category}"],
        })
    return rows

train_rows = build(TRAIN, "persona")
validation_rows = build(VALIDATION, "persona-val")
for name, rows in (("personality_train.jsonl", train_rows), ("personality_validation.jsonl", validation_rows)):
    (OUT / name).write_text("".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows))
    print(f"{name}: {len(rows)}")
